mapper.select:
SELECT id, task_id, attempt, stage, status, started_at, finished_at, error_code, error_message
FROM document_index_step
WHERE task_id = #{id}
ORDER BY attempt, id
LIMIT #{limit}
OFFSET #{offset}

mapper.update:
UPDATE document_index_task
SET stage = #{stage}
WHERE id = #{id}

mapper.select:
SELECT count(*)
FROM document_index_step
WHERE task_id = #{id}

mapper.update:
UPDATE document_version
SET status = #{stage}
WHERE document_id = #{documentId} AND version_no = #{version}

UPDATE document
SET status = #{stage}
WHERE id = #{documentId} AND current_version = #{version} AND NOT deleted
